SELECT p.id AS position_id, p.entry_price, p.stop_loss, s0.take_profit AS original_tp, MIN(s.latest_price) AS min_close_60m, MAX(s.latest_price) AS max_close_60m, MIN(CASE WHEN s.latest_price >= s0.take_profit THEN s.generated_at END) AS first_tp_close, MIN(CASE WHEN s.latest_price <= p.stop_loss THEN s.generated_at END) AS first_sl_close FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s0 ON s0.id=p.signal_id JOIN crypto_ai.trade_signal s ON s.symbol=p.symbol AND s.interval_code='1m' AND s.generated_at BETWEEN p.closed_at AND p.closed_at + INTERVAL 60 MINUTE WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id, p.entry_price, p.stop_loss, s0.take_profit ORDER BY p.id;
SHOW COLUMNS FROM crypto_ai.candle;